// File: src/worker.ts, Lines 5-12
async fetch(request: Request, environment: Env, context: ExecutionContext): Promise<Response> {
  const url = new URL(request.url);

  if (request.method === 'GET' || request.method === 'HEAD') {
    const slashRoute = routeByPath.get(`${url.pathname}/`);
    if (!url.pathname.endsWith('/') && slashRoute?.slashMode === 'slash') {
      url.pathname = `${url.pathname}/`;
      return Response.redirect(url, 301);
    }
  }
}
```
